/** The discharge summary. Final = signed; the signer's stamp (name, designation, licence) is frozen at signing. */
export interface DischargeSummaryOut {
  summary_id: number;
  admission_id: number;
  patient_id: number;
  outcome: "Home" | "Transferred" | "LAMA" | "Absconded" | "Died";
  condition_at_discharge: "Recovered" | "Improved" | "Unchanged" | "Deteriorated" | null;
  reason_for_admission: string | null;
  final_diagnosis: string | null;
  icd_codes: string[];
  /** The codes with their titles and WHO URIs */
  icd_terms: IcdTermOut[];
  significant_findings: string | null;
  procedures_and_treatment: string | null;
  response_to_treatment: string | null;
  discharge_medications: string | null;
  follow_up_instructions: string | null;
  follow_up_date: string | null;
  receiving_hospital: string | null;
  transfer_reason: string | null;
  transfer_arrangements: string | null;
  outcome_note: string | null;
  status: "Draft" | "Final";
  created_by: number;
  created_by_name: string;
  created_at: string;
  signed_by: number | null;
  signed_at: string | null;
  signer_name: string | null;
  signer_designation: string | null;
  /** e.g. "PMDC 12345-P" */
  signer_license: string | null;
  row_version: number;
}

/** A code as stored in a record, with its title and WHO URI from the code list (the ICD-11 licence asks for code, title and URI together wherever codes are sent). `title` is null only for a code no list has. */
export interface IcdTermOut {
  code: string;
  system: "ICD-11" | "ICD-10";
  title: string | null;
  /** ICD-11: the WHO URI of the entity (null for ICD-10) */
  uri: string | null;
}

export interface DischargeSummaryCorrectionOut {
  correction_id: number;
  field: "reason_for_admission" | "final_diagnosis" | "significant_findings" | "procedures_and_treatment" | "response_to_treatment" | "discharge_medications" | "follow_up_instructions" | "transfer" | "general";
  correction_text: string;
  correction_reason: string;
  corrected_by_name: string;
  created_at: string;
}

/** One active staff member as a picker shows them (GET /staff/lookup): the facts on their badge and the registration their stamp prints, nothing else. */
export interface StaffLookupOut {
  /** The id a form's staff field takes (contrast_doctor_id, employee_id, ...) */
  employee_id: number;
  emp_number: string;
  full_name: string;
  designation: string;
  department_name: string | null;
  /** The council they are registered with (PMDC: a doctor or dentist; PNC: a nurse); null: none */
  license_type: "PMDC" | "PNC" | "Other" | null;
  /** As their stamp prints it, e.g. "PMDC 12345-P"; null: no number on file */
  registration: string | null;
}

/** Ward nurse: my rostered beds this shift (doses due, last vitals) — GET /api/v1/ipd/my-beds (who may call: holders of ipd.flowsheet.record). */
export function myBeds(): Promise<MyBedOut[]> {
  return api<MyBedOut[]>("GET", `/ipd/my-beds`, undefined);
}

/** My duties (two weeks from today by default) — GET /api/v1/self/roster (who may call: holders of self.profile.view). */
export function myDuties(query?: { date_from?: string | null; date_to?: string | null }): Promise<RosterEntryOut[]> {
  return api<RosterEntryOut[]>("GET", withQuery(`/self/roster`, query), undefined);
}

/** Confirm a bed was cleaned (where no badge station records it) — POST /api/v1/beds/{bed_id}/mark-cleaned (who may call: holders of ipd.bed.mark_cleaned). */
export function markCleaned(bed_id: number, body: CleanedIn | null): Promise<BedCleaningOut> {
  return api<BedCleaningOut>("POST", `/beds/${bed_id}/mark-cleaned`, body, { idempotent: true });
}

/** Printable discharge summary, or referral slip for a transfer — GET /api/v1/admissions/{admission_id}/discharge-summary/print-payload (who may call: holders of ipd.discharge.initiate or clinical.encounter.view or patient.emr.view). */
export function dischargeSummaryPrint(admission_id: number): Promise<PrintOut_DischargeSummaryPrintFieldsOut_> {
  return api<PrintOut_DischargeSummaryPrintFieldsOut_>("GET", `/admissions/${admission_id}/discharge-summary/print-payload`, undefined);
}

/** The signed discharge summary as a PDF — GET /api/v1/admissions/{admission_id}/discharge-summary/pdf (who may call: holders of ipd.discharge.initiate or clinical.encounter.view or patient.emr.view). */
export function dischargeSummaryPdf(admission_id: number): Promise<unknown> {
  return api<unknown>("GET", `/admissions/${admission_id}/discharge-summary/pdf`, undefined);
}

/** Find a staff member for a form (badge facts only) — GET /api/v1/staff/lookup (who may call: any logged-in user). */
export function lookupStaff(query: { q: string; department_id?: number | null; license_type?: "PMDC" | "PNC" | null; limit?: number }): Promise<StaffLookupOut[]> {
  return api<StaffLookupOut[]>("GET", withQuery(`/staff/lookup`, query), undefined);
}

